import sys, tempfile, cozum
from pathlib import Path
with tempfile.TemporaryDirectory() as d:
    yol = Path(d) / "ayar.txt"
    if sys.argv[1] == "var":
        yol.write_bytes(sys.argv[2].encode("utf-8"))
    if sys.argv[1] == "klasor":
        yol.mkdir()
    try:
        print(repr(cozum.oku_ya_da_bos(yol)))
    except Exception as e:
        print("yukarıya geldi:", type(e).__name__ in ("IsADirectoryError", "PermissionError"))
